import { Suspense, ViewTransition, type ReactNode } from 'react'

type ViewSuspenseProps = {
  children: ReactNode
  fallback: ReactNode
}

export function ViewSuspense({ children, fallback }: ViewSuspenseProps) {
  return (
    <Suspense
      fallback={
        <ViewTransition default="none" exit="skeleton-exit">
          {fallback}
        </ViewTransition>
      }
    >
      <ViewTransition default="none" enter="content-enter">
        {children}
      </ViewTransition>
    </Suspense>
  )
}

